CREATE VIEW v90166 AS SELECT ST_DISTANCE(ST_GEOMFROMTEXT('geometrycollection(polygon((0 0,0 10,10 10,10 0,0 0)))'), ST_GEOMFROMTEXT('point(100 100)')), GET_DD_INDEX_SUB_PART_LENGTH(NULL, NULL, NULL, NULL, NULL), GROUPING(x8.x1), SUM(LEAST(x8.v89604, x8.v89605)), SUM(1) FROM v89790 AS x8 GROUP BY x8.x2 WITH ROLLUP